import java.io.*;
import java.util.*;
import java.text.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/employees.csv";

        List<String> lines = new ArrayList<>();
        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = br.readLine()) != null) {
            lines.add(line);
        }
        br.close();

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        for (int i = 1; i < lines.size(); i++) {
            String[] parts = lines.get(i).split(",");
            if (parts.length < 4) continue;
            String name = parts[1].trim();
            String department = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim());

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCount.put(department, deptCount.getOrDefault(department, 0) + 1);
            totalBudget += salary;

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }
        }

        NumberFormat intFormat = NumberFormat.getIntegerInstance(Locale.US);
        NumberFormat doubleFormat = NumberFormat.getNumberInstance(Locale.US);
        doubleFormat.setMinimumFractionDigits(2);
        doubleFormat.setMaximumFractionDigits(2);

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            String dept = entry.getKey();
            List<Double> salaries = entry.getValue();
            double avg = salaries.stream().mapToDouble(Double::doubleValue).average().orElse(0);
            sb.append("  ").append(dept).append(": $").append(doubleFormat.format(avg)).append("\n");
        }

        sb.append("\n");
        sb.append("Highest Paid: ").append(highestName).append(" ($").append(intFormat.format((long) highestSalary)).append(")\n");
        sb.append("\n");
        sb.append("Departments with >2 employees:\n");

        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                sb.append("  ").append(entry.getKey()).append(" (").append(entry.getValue()).append(" employees)\n");
            }
        }

        sb.append("\n");
        sb.append("Total Budget: $").append(intFormat.format((long) totalBudget)).append("\n");

        System.out.print(sb.toString());
    }
}

