import * as fs from 'fs';

const logFile = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/app.log';
const content = fs.readFileSync(logFile, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

interface LogEntry {
  timestamp: string;
  level: string;
  component: string;
  message: string;
}

const entries: LogEntry[] = [];
const regex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
  const match = line.match(regex);
  if (match) {
    entries.push({
      timestamp: match[1],
      level: match[2],
      component: match[3],
      message: match[4]
    });
  }
}

const levelCounts: Map<string, number> = new Map();
for (const entry of entries) {
  levelCounts.set(entry.level, (levelCounts.get(entry.level) || 0) + 1);
}
const sortedLevels = Array.from(levelCounts.entries()).sort((a, b) => a[0].localeCompare(b[0]));

const errorComponentCounts: Map<string, number> = new Map();
for (const entry of entries) {
  if (entry.level === 'ERROR') {
    errorComponentCounts.set(entry.component, (errorComponentCounts.get(entry.component) || 0) + 1);
  }
}
let topErrorComponent = '';
let topErrorCount = 0;
for (const [comp, count] of errorComponentCounts) {
  if (count > topErrorCount) {
    topErrorCount = count;
    topErrorComponent = comp;
  }
}

const errorMessages = new Set<string>();
for (const entry of entries) {
  if (entry.level === 'ERROR') {
    errorMessages.add(entry.message);
  }
}
const sortedErrorMessages = Array.from(errorMessages).sort((a, b) => a.localeCompare(b));

const hourCounts: Map<string, number> = new Map();
for (const entry of entries) {
  const hour = entry.timestamp.substring(11, 13);
  hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}
let busiestHour = '';
let busiestCount = 0;
for (const [hour, count] of hourCounts) {
  if (count > busiestCount) {
    busiestCount = count;
    busiestHour = hour;
  }
}

console.log('=== Log Analysis ===');
console.log('');
console.log('Entries by Level:');
for (const [level, count] of sortedLevels) {
  console.log(`  ${level}: ${count}`);
}
console.log('');
console.log(`Component with Most Errors: ${topErrorComponent} (${topErrorCount} errors)`);
console.log('');
console.log('Unique Error Messages:');
for (const msg of sortedErrorMessages) {
  console.log(`  - ${msg}`);
}
console.log('');
console.log(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

