import Foundation

let filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/employees.csv"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").map { $0.replacingOccurrences(of: "\r", with: "") }.filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let dataLines = Array(lines.dropFirst())

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []

for line in dataLines {
    let fields = line.components(separatedBy: ",")
    if fields.count >= 6 {
        let name = fields[1].trimmingCharacters(in: .whitespaces)
        let department = fields[2].trimmingCharacters(in: .whitespaces)
        let salaryStr = fields[3].trimmingCharacters(in: .whitespaces)
        let salary = Double(salaryStr) ?? 0
        employees.append(Employee(name: name, department: department, salary: salary))
    }
}

func formatIntWithCommas(_ value: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.maximumFractionDigits = 0
    formatter.minimumFractionDigits = 0
    return formatter.string(from: NSNumber(value: value)) ?? "\(value)"
}

func formatDoubleWithCommas(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.maximumFractionDigits = 2
    formatter.minimumFractionDigits = 2
    return formatter.string(from: NSNumber(value: value)) ?? String(format: "%.2f", value)
}

var deptSalaries: [String: [Double]] = [:]
for emp in employees {
    deptSalaries[emp.department, default: []].append(emp.salary)
}

let sortedDepts = deptSalaries.keys.sorted()

print("=== Salary Report ===")
print("")
print("Average Salary by Department:")
for dept in sortedDepts {
    let salaries = deptSalaries[dept]!
    let avg = salaries.reduce(0, +) / Double(salaries.count)
    print("  \(dept): $\(formatDoubleWithCommas(avg))")
}
print("")

let highestEmp = employees.max { $0.salary < $1.salary }!
print("Highest Paid: \(highestEmp.name) ($\(formatIntWithCommas(Int(highestEmp.salary))))")
print("")

var deptCounts: [String: Int] = [:]
for emp in employees {
    deptCounts[emp.department, default: 0] += 1
}

let deptsOver2 = deptCounts.filter { $0.value > 2 }.sorted { $0.key < $1.key }

print("Departments with >2 employees:")
for (dept, count) in deptsOver2 {
    print("  \(dept) (\(count) employees)")
}
print("")

let totalBudget = employees.reduce(0) { $0 + Int($1.salary) }
print("Total Budget: $\(formatIntWithCommas(totalBudget))")

