public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/app.log";

        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (!line.trim().isEmpty()) {
                    lines.add(line.trim());
                }
            }
        }

        Pattern pattern = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):(\\d{2}):(\\d{2}))\\] (\\S+) \\(([^)]+)\\) - (.+)$");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorComponentCounts = new TreeMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new TreeMap<>();

        for (String line : lines) {
            Matcher m = pattern.matcher(line);
            if (m.matches()) {
                String hour = m.group(2);
                String level = m.group(5);
                String component = m.group(6);
                String message = m.group(7);

                levelCounts.merge(level, 1, Integer::sum);
                hourCounts.merge(hour, 1, Integer::sum);

                if (level.equals("ERROR")) {
                    errorComponentCounts.merge(component, 1, Integer::sum);
                    errorMessages.add(message);
                }
            }
        }

        String topErrorComponent = "";
        int maxErrors = 0;
        for (Map.Entry<String, Integer> entry : errorComponentCounts.entrySet()) {
            if (entry.getValue() > maxErrors) {
                maxErrors = entry.getValue();
                topErrorComponent = entry.getKey();
            }
        }

        String busiestHour = "";
        int maxEntries = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > maxEntries) {
                maxEntries = entry.getValue();
                busiestHour = entry.getKey();
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            sb.append("  ").append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        sb.append("\n");
        sb.append("Component with Most Errors: ").append(topErrorComponent).append(" (").append(maxErrors).append(" errors)\n");
        sb.append("\n");
        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");
        sb.append("Busiest Hour: ").append(busiestHour).append(":00 (").append(maxEntries).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

