import Foundation

let filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/app.log"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

let pattern = "^\\[([^\\]]+)\\] (\\S+) \\(([^)]+)\\) - (.+)$"
let regex = try! NSRegularExpression(pattern: pattern)

for line in lines {
    let range = NSRange(line.startIndex..<line.endIndex, in: line)
    guard let match = regex.firstMatch(in: line, options: [], range: range), match.numberOfRanges >= 5 else { continue }

    let timestamp = (line as NSString).substring(with: match.range(at: 1))
    let level = (line as NSString).substring(with: match.range(at: 2))
    let component = (line as NSString).substring(with: match.range(at: 3))
    let message = (line as NSString).substring(with: match.range(at: 4))

    levelCounts[level, default: 0] += 1

    if timestamp.count >= 13 {
        let hourStr = String(timestamp[timestamp.index(timestamp.startIndex, offsetBy: 11)...timestamp.index(timestamp.startIndex, offsetBy: 12)])
        if let hour = Int(hourStr) {
            hourCounts[hour, default: 0] += 1
        }
    }

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for (level, count) in levelCounts.sorted(by: { $0.key < $1.key }) {
    print("  \(level): \(count)")
}
print("")
if let (comp, count) = errorComponentCounts.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(comp) (\(count) errors)")
}
print("")
print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")
if let (hour, count) = hourCounts.max(by: { $0.value < $1.value }) {
    print(String(format: "Busiest Hour: %02d:00 (\(count) entries)", hour))
}

