use std::collections::BTreeMap;
use std::fs;

fn format_int_with_commas(n: i64) -> String {
    let s = n.to_string();
    let negative = n < 0;
    let digits = if negative { &s[1..] } else { &s };
    let mut result = String::new();
    for (i, c) in digits.chars().rev().enumerate() {
        if i > 0 && i % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if negative {
        result.push('-');
    }
    result.reverse();
    result
}

fn main() {
    let content = fs::read_to_string(
        "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/employees.csv",
    )
    .expect("Failed to read file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].trim();
        let department = fields[2].trim();
        let salary: f64 = fields[3].trim().parse().expect("Failed to parse salary");

        dept_salaries
            .entry(department.to_string())
            .or_insert_with(Vec::new)
            .push(salary);

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name.to_string();
        }

        total_budget += salary;
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, salaries) in &dept_salaries {
        let avg: f64 = salaries.iter().sum::<f64>() / salaries.len() as f64;
        let avg_str = format!("{:.2}", avg);
        let parts: Vec<&str> = avg_str.split('.').collect();
        let int_part: i64 = parts[0].parse().unwrap();
        let formatted_int = format_int_with_commas(int_part);
        println!("  {}: ${}.{}", dept, formatted_int, parts[1]);
    }

    println!();
    println!(
        "Highest Paid: {} (${})",
        highest_paid_name,
        format_int_with_commas(highest_paid_salary as i64)
    );

    println!();
    println!("Departments with >2 employees:");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            println!("  {} ({} employees)", dept, salaries.len());
        }
    }

    println!();
    println!(
        "Total Budget: ${}",
        format_int_with_commas(total_budget as i64)
    );
}

