use std::fs;

fn main() {
    let content = fs::read_to_string(
        "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/app.log",
    )
    .expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = line.find(']').expect("No closing bracket");
        let timestamp = &line[1..close_bracket];

        // Extract hour from timestamp "YYYY-MM-DD HH:MM:SS"
        let hour: u32 = timestamp[11..13].parse().unwrap_or(0);
        *hour_counts.entry(hour).or_insert(0) += 1;

        // After "] "
        let rest = &line[close_bracket + 2..];

        // LEVEL
        let space_pos = rest.find(' ').expect("No space after level");
        let level = &rest[..space_pos];
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // After " LEVEL "
        let after_level = &rest[space_pos + 1..];

        // (component)
        let open_paren = after_level.find('(').expect("No open paren");
        let close_paren = after_level.find(')').expect("No close paren");
        let component = &after_level[open_paren + 1..close_paren];

        // After ") - message"
        let after_close_paren = &after_level[close_paren + 1..];
        let message = after_close_paren.trim_start_matches(" - ");

        if level == "ERROR" {
            *error_component_counts
                .entry(component.to_string())
                .or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(k, v)| (k.as_str(), *v))
        .unwrap_or(("N/A", 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(h, c)| (*h, *c))
        .unwrap_or((0, 0));
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

