        strncpy(employees[count].name, fields[1], 255);
        employees[count].name[255] = '\0';
        strncpy(employees[count].department, fields[2], 255);
        employees[count].department[255] = '\0';
        employees[count].salary = atof(fields[3]);
        count++;
    }
    fclose(fp);

    if (count == 0) {
        printf("=== Salary Report ===\n\nAverage Salary by Department:\n\nHighest Paid: N/A ($0)\n\nDepartments with >2 employees:\n\nTotal Budget: $0\n");
        free(employees);
        return 0;
    }

    /* Collect unique departments */
    char **depts = malloc((size_t)count * sizeof(char *));
    int ndepts = 0;
    for (int i = 0; i < count; i++) {
        int found = 0;
        for (int j = 0; j < ndepts; j++) {
            if (strcmp(depts[j], employees[i].department) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            depts[ndepts] = strdup(employees[i].department);
            ndepts++;
        }
    }

    qsort(depts, (size_t)ndepts, sizeof(char *), compare_depts);

    double *sums = calloc((size_t)ndepts, sizeof(double));
    int *cnts = calloc((size_t)ndepts, sizeof(int));
    double total = 0.0;
    double max_salary = -1.0;
    int max_idx = 0;

    for (int i = 0; i < count; i++) {
        total += employees[i].salary;
        if (employees[i].salary > max_salary) {
            max_salary = employees[i].salary;
            max_idx = i;
        }
        for (int j = 0; j < ndepts; j++) {
            if (strcmp(depts[j], employees[i].department) == 0) {
                sums[j] += employees[i].salary;
                cnts[j]++;
                break;
            }
        }
    }

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < ndepts; i++) {
        char buf[128];
        double avg = cnts[i] > 0 ? sums[i] / cnts[i] : 0.0;
        format_commas(avg, buf, 2);
        printf("  %s: $%s\n", depts[i], buf);
    }
    printf("\n");
    {
        char buf[128];
        format_commas(max_salary, buf, 0);
        printf("Highest Paid: %s ($%s)\n", employees[max_idx].name, buf);
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < ndepts; i++) {
        if (cnts[i] > 2) {
            printf("  %s (%d employees)\n", depts[i], cnts[i]);
        }
    }
    printf("\n");
    {
        char buf[128];
        format_commas(total, buf, 0);
        printf("Total Budget: $%s\n", buf);
    }

    for (int i = 0; i < ndepts; i++) free(depts[i]);
    free(depts);
    free(sums);
    free(cnts);
    free(employees);
    return 0;
