import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface GraphData {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/graph.json';
    const raw = fs.readFileSync(filePath, 'utf-8');
    const data: GraphData = JSON.parse(raw);

    const adj: Map<string, Array<[string, number]>> = new Map();
    for (const node of data.nodes) {
        adj.set(node, []);
    }
    for (const edge of data.edges) {
        adj.get(edge.from)!.push([edge.to, edge.weight]);
        adj.get(edge.to)!.push([edge.from, edge.weight]);
    }

    const dist: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of data.nodes) {
        dist.set(node, Infinity);
    }
    dist.set('A', 0);

    for (let i = 0; i < data.nodes.length; i++) {
        let u: string | null = null;
        let minDist = Infinity;
        for (const node of data.nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                u = node;
            }
        }

        if (u === null) break;

        visited.add(u);

        for (const [v, w] of adj.get(u)!) {
            if (!visited.has(v)) {
                const newDist = dist.get(u)! + w;
                if (newDist < dist.get(v)!) {
                    dist.set(v, newDist);
                }
            }
        }
    }

    const lines: string[] = [];
    lines.push('=== Shortest Paths from A ===');
    lines.push('');

    const sortedNodes = [...data.nodes].sort();
    for (const node of sortedNodes) {
        const d = dist.get(node)!;
        lines.push(`A -> ${node}: ${d}`);
    }

    process.stdout.write(lines.join('\n') + '\n');
}

main();

