    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();

        String inner = json.substring(json.indexOf('[') + 1, json.lastIndexOf(']'));

        List<String> objects = new ArrayList<>();
        int depth = 0;
        int start = -1;
        for (int i = 0; i < inner.length(); i++) {
            char c = inner.charAt(i);
            if (c == '{') {
                if (depth == 0) start = i;
                depth++;
            } else if (c == '}') {
                depth--;
                if (depth == 0) {
                    objects.add(inner.substring(start, i + 1));
                }
            }
        }

        List<String> names = new ArrayList<>();
        List<Double> prices = new ArrayList<>();

        for (String obj : objects) {
            String name = extractString(obj, "name");
            double price = extractNumber(obj, "price");
            names.add(name);
            prices.add(price);
        }

        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < names.size(); i++) {
            if (prices.get(i) > 50.00) {
                indices.add(i);
            }
        }

        indices.sort((a, b) -> names.get(a).compareTo(names.get(b)));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        double total = 0;
        for (int idx : indices) {
            System.out.println(names.get(idx) + ": $" + String.format("%.2f", prices.get(idx)));
            total += prices.get(idx);
        }
        System.out.println();
        System.out.println("Count: " + indices.size());
        System.out.println("Total: $" + String.format("%.2f", total));
    }

    static String extractString(String obj, String key) {
        String pattern = "\"" + key + "\"\\s*:\\s*\"";
        Matcher m = Pattern.compile(pattern).matcher(obj);
        if (m.find()) {
            int i = m.end();
            StringBuilder val = new StringBuilder();
            while (i < obj.length()) {
                char c = obj.charAt(i);
                if (c == '\\') {
                    char next = obj.charAt(i + 1);
                    switch (next) {
                        case '"': val.append('"'); break;
                        case '\\': val.append('\\'); break;
                        case 'n': val.append('\n'); break;
                        case 't': val.append('\t'); break;
                        case 'r': val.append('\r'); break;
                        default: val.append(next); break;
                    }
                    i += 2;
                } else if (c == '"') {
                    break;
                } else {
                    val.append(c);
                    i++;
                }
            }
            return val.toString();
        }
        return "";
    }

    static double extractNumber(String obj, String key) {
        String pattern = "\"" + key + "\"\\s*:\\s*";
        Matcher m = Pattern.compile(pattern).matcher(obj);
        if (m.find()) {
            int start = m.end();
            int end = start;
            while (end < obj.length()) {
                char c = obj.charAt(end);
                if (Character.isDigit(c) || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E') {
                    end++;
                } else {
                    break;
                }
            }
            return Double.parseDouble(obj.substring(start, end));
        }
        return 0;
    }
}

