import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_wc6fq665/graph.json";
        String json = new String(Files.readAllBytes(Paths.get(path)));

        List<String> nodes = new ArrayList<>();
        Map<String, Map<String, Integer>> adj = new HashMap<>();

        // Parse nodes
        int nodesKey = json.indexOf("\"nodes\"");
        int arrStart = json.indexOf('[', nodesKey);
        int arrEnd = json.indexOf(']', arrStart);
        String nodesStr = json.substring(arrStart + 1, arrEnd);
        for (String part : nodesStr.split(",")) {
            String s = part.trim().replace("\"", "");
            if (!s.isEmpty()) nodes.add(s);
        }
        for (String n : nodes) adj.put(n, new HashMap<>());

        // Parse edges
        int edgesKey = json.indexOf("\"edges\"");
        int eArrStart = json.indexOf('[', edgesKey);
        int depth = 0;
        int eArrEnd = eArrStart;
        for (int i = eArrStart; i < json.length(); i++) {
            if (json.charAt(i) == '[') depth++;
            if (json.charAt(i) == ']') depth--;
            if (depth == 0) { eArrEnd = i; break; }
        }
        String edgesStr = json.substring(eArrStart + 1, eArrEnd);

        int pos = 0;
        while (pos < edgesStr.length()) {
            int objStart = edgesStr.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = edgesStr.indexOf('}', objStart);
            String edgeObj = edgesStr.substring(objStart, objEnd + 1);

            String from = extractString(edgeObj, "from");
            String to = extractString(edgeObj, "to");
            int weight = extractInt(edgeObj, "weight");

            adj.get(from).put(to, weight);
            adj.get(to).put(from, weight);

            pos = objEnd + 1;
        }

        // Dijkstra's algorithm
        Map<String, Integer> dist = new HashMap<>();
        Set<String> visited = new HashSet<>();
        for (String n : nodes) dist.put(n, Integer.MAX_VALUE);
        dist.put("A", 0);

        for (int i = 0; i < nodes.size(); i++) {
            String u = null;
            int minDist = Integer.MAX_VALUE;
            for (String n : nodes) {
                if (!visited.contains(n) && dist.get(n) < minDist) {
                    minDist = dist.get(n);
                    u = n;
                }
            }
            if (u == null) break;
            visited.add(u);

            for (Map.Entry<String, Integer> e : adj.get(u).entrySet()) {
                String v = e.getKey();
                int w = e.getValue();
                if (!visited.contains(v) && dist.get(u) + w < dist.get(v)) {
                    dist.put(v, dist.get(u) + w);
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);
        for (String node : sorted) {
            System.out.println("A -> " + node + ": " + dist.get(node));
        }
    }

    static String extractString(String s, String key) {
        int idx = s.indexOf("\"" + key + "\"");
        idx = s.indexOf(':', idx);
        idx = s.indexOf('"', idx + 1);
        int end = s.indexOf('"', idx + 1);
        return s.substring(idx + 1, end);
    }

    static int extractInt(String s, String key) {
        int idx = s.indexOf("\"" + key + "\"");
        idx = s.indexOf(':', idx) + 1;
        while (idx < s.length() && (s.charAt(idx) == ' ' || s.charAt(idx) == '\t')) idx++;
        int end = idx;
        while (end < s.length() && (Character.isDigit(s.charAt(end)) || s.charAt(end) == '-')) end++;
        return Integer.parseInt(s.substring(idx, end));
    }
}

