            let ext = (name as NSString).pathExtension
            let extKey = ext.isEmpty ? "(no extension)" : "." + ext

            let info = FileInfo(relativePath: relativePath, lines: lines, chars: chars)
            filesByExt[extKey, default: []].append(info)
        default:
            break
        }
    }
