function walkDir(dir: string, root: string, files: Map<string, FileInfo[]>, visited: Set<string>): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    if (entry.isSymbolicLink()) {
      continue;
    }

    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(root, fullPath).split(path.sep).join('/');

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      walkDir(fullPath, root, files, visited);
    } else if (entry.isFile()) {
      let buffer: Buffer;
      try {
        buffer = fs.readFileSync(fullPath);
      } catch {
        continue;
      }
      const lines = countLines(buffer);
      const chars = buffer.length;
      const ext = path.extname(entry.name);
      if (!files.has(ext)) {
        files.set(ext, []);
      }
      files.get(ext)!.push({ relativePath, lines, chars });
    }
  }
}

const files = new Map<string, FileInfo[]>();
const visited = new Set<string>();
try {
  visited.add(fs.realpathSync(ROOT));
} catch {
  process.stdout.write('=== File Tree Analysis ===\n\n\nTotal: 0 files, 0 lines, 0 characters\n');
  process.exit(0);
}
walkDir(ROOT, ROOT, files, visited);

const extensions = Array.from(files.keys()).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

for (const ext of extensions) {
  files.get(ext)!.sort((a, b) => (a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0));
}

let output = '=== File Tree Analysis ===\n\n';

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of extensions) {
  const extFiles = files.get(ext)!;
  const extLines = extFiles.reduce((sum, f) => sum + f.lines, 0);
  const extChars = extFiles.reduce((sum, f) => sum + f.chars, 0);

  output += `Extension: ${ext}\n`;
  output += `  Files: ${extFiles.length}\n`;
  output += `  Total Lines: ${extLines}\n`;
  output += `  Total Characters: ${extChars}\n`;

  for (const f of extFiles) {
    output += `    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars\n`;
  }

  totalFiles += extFiles.length;
  totalLines += extLines;
