#include <string.h>

static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) { pclose(fp); return NULL; }

    size_t len = 0;
    size_t n;
    while ((n = fread(buf + len, 1, cap - len - 1, fp)) > 0) {
        len += n;
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); pclose(fp); return NULL; }
            buf = tmp;
        }
    }
    buf[len] = '\0';
    pclose(fp);

    while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
                       buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

int main(void) {
    char *hostname = run_command("hostname");
    char *os       = run_command("uname -s");
    char *arch     = run_command("uname -m");
    char *username = run_command("whoami");

    if (!hostname) { free(hostname); hostname = strdup(""); }
    if (!os)       { free(os);       os       = strdup(""); }
    if (!arch)     { free(arch);     arch     = strdup(""); }
