         + M[0][2] * (M[1][0] * M[2][1] - M[1][1] * M[2][0])
}

func pad4(_ n: Int) -> String {
    let s = String(n)
    if s.count >= 4 { return s }
    return String(repeating: " ", count: 4 - s.count) + s
}

