use std::collections::HashMap;
use std::fs;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len() && self.data[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        assert_eq!(self.next_char(), Some(c), "Expected '{}'", c);
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => { self.pos += 4; Json::Bool(true) }
            Some('f') => { self.pos += 5; Json::Bool(false) }
            Some('n') => { self.pos += 4; Json::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut obj = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next_char();
            return Json::Object(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}}' in object"),
            }
        }
        Json::Object(obj)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next_char();
            return Json::Array(arr);
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        Json::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next_char() {
                Some('"') => break,
                Some('\\') => {
                    match self.next_char() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('u') => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                let c = self.next_char().unwrap();
                                hex.push(c);
                            }
                            let code = u32::from_str_radix(&hex, 16).unwrap();
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        Some(c) => { s.push('\\'); s.push(c); }
                        None => panic!("Unexpected end in escape"),
                    }
                }
                Some(c) => s.push(c),
                None => panic!("Unexpected end of string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        self.skip_whitespace();
        let start = self.pos;
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.data[start..self.pos].iter().collect();
        Json::Number(s.parse::<f64>().unwrap())
    }
}

fn format_dist(d: f64) -> String {
    if d == d.trunc() && d.abs() < 1e15 {
        format!("{}", d as i64)
    } else {
        format!("{}", d)
    }
}

