        total_lines += n_lines;
        total_chars += n_chars;
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn get_extension(path: &str) -> String {
    let p = Path::new(path);
    match p.extension() {
        Some(ext) => format!(".{}", ext.to_string_lossy()),
        None => String::new(),
    }
}

fn walk(dir: &Path, root: &Path, files: &mut Vec<(String, u64, u64)>, visited: &mut HashSet<PathBuf>) {
