        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let path = entry.path();
        let file_type = match entry.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };

        if file_type.is_symlink() {
            continue;
        }

        if file_type.is_dir() {
            let canonical = match path.canonicalize() {
                Ok(c) => c,
                Err(_) => continue,
            };
            if visited.contains(&canonical) {
                continue;
            }
            visited.insert(canonical);
            walk(&path, root, files, visited);
        } else if file_type.is_file() {
            let rel_path = path.strip_prefix(root).unwrap().to_string_lossy().to_string();
            let (lines, chars) = count_file(&path);
            files.push((rel_path, lines, chars));
        }
    }
}

fn count_file(path: &Path) -> (u64, u64) {
    let metadata = fs::metadata(path).unwrap();
    let chars = metadata.len();

    let file = File::open(path).unwrap();
    let reader = BufReader::new(file);
    let lines = reader.lines().count() as u64;

    (lines, chars)
}

