                case 'r':  if(len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\r'; break;
                case 't':  if(len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\t'; break;
