                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (unsigned)(h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (unsigned)(h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (unsigned)(h - 'A' + 10);
                    }
                    if (code < 0x80) {
                        if(len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]=(char)code;
                    } else if (code < 0x800) {
                        if(len+2>=cap){cap*=2;buf=realloc(buf,cap);}
