static JsonValue *parse_obj(Parser *p) {
    p->pos++; /* { */
    JsonValue *obj = new_value(JSON_OBJECT);
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == '}') { p->pos++; return obj; }
    while (1) {
