        obj->object.pairs[obj->object.count].value = val;
        obj->object.count++;
        skip_ws(p);
        if (p->pos < p->len && p->src[p->pos] == ',') { p->pos++; }
        else break;
    }
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == '}') p->pos++;
    return obj;
}

static JsonValue *parse_arr(Parser *p) {
    p->pos++; /* [ */
    JsonValue *arr = new_value(JSON_ARRAY);
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == ']') { p->pos++; return arr; }
    while (1) {
