        if (p->pos < p->len && p->src[p->pos] == ',') { p->pos++; }
        else break;
    }
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == ']') p->pos++;
    return arr;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return new_value(JSON_NULL);
    char c = p->src[p->pos];
    if (c == '{') return parse_obj(p);
    if (c == '[') return parse_arr(p);
    if (c == '"') {
        JsonValue *v = new_value(JSON_STRING);
        v->string = parse_str(p);
        return v;
    }
    if (c == 't') { p->pos += 4; JsonValue *v = new_value(JSON_BOOL); v->boolean = 1; return v; }
    if (c == 'f') { p->pos += 5; JsonValue *v = new_value(JSON_BOOL); v->boolean = 0; return v; }
    if (c == 'n') { p->pos += 4; return new_value(JSON_NULL); }
    /* number */
    JsonValue *v = new_value(JSON_NUMBER);
    char *end;
    v->number = strtod(p->src + p->pos, &end);
    p->pos += (size_t)(end - (p->src + p->pos));
    return v;
}

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (fread(buf, 1, (size_t)sz, f) != (size_t)sz) { fprintf(stderr, "Read error\n"); exit(1); }
    buf[sz] = '\0';
    fclose(f);
    return buf;
}

static JsonValue *deep_copy(const JsonValue *src) {
    if (!src) return NULL;
    JsonValue *dst = new_value(src->type);
    switch (src->type) {
        case JSON_NULL: break;
        case JSON_BOOL: dst->boolean = src->boolean; break;
        case JSON_NUMBER: dst->number = src->number; break;
        case JSON_STRING: dst->string = strdup(src->string); break;
        case JSON_ARRAY:
            dst->array.count = src->array.count;
            dst->array.cap = src->array.count;
            if (src->array.count) {
                dst->array.items = (JsonValue **)malloc(src->array.count * sizeof(JsonValue *));
                for (size_t i = 0; i < src->array.count; i++)
                    dst->array.items[i] = deep_copy(src->array.items[i]);
            }
            break;
        case JSON_OBJECT:
            dst->object.count = src->object.count;
            dst->object.cap = src->object.count;
            if (src->object.count) {
                dst->object.pairs = (JsonPair *)malloc(src->object.count * sizeof(JsonPair));
                for (size_t i = 0; i < src->object.count; i++) {
                    dst->object.pairs[i].key = strdup(src->object.pairs[i].key);
                    dst->object.pairs[i].value = deep_copy(src->object.pairs[i].value);
                }
            }
            break;
    }
    return dst;
}

static JsonPair *find_key(const JsonValue *obj, const char *key) {
    if (!obj || obj->type != JSON_OBJECT) return NULL;
    for (size_t i = 0; i < obj->object.count; i++)
        if (strcmp(obj->object.pairs[i].key, key) == 0)
            return (JsonPair *)&obj->object.pairs[i];
    return NULL;
}

/* Canonical compact string for equality comparison */
static void canon_ensure(char **buf, size_t *len, size_t *cap, size_t need) {
    if (*len + need + 1 > *cap) {
        *cap = (*len + need + 1) * 2;
        *buf = (char *)realloc(*buf, *cap);
    }
}

static void to_canon(const JsonValue *v, char **buf, size_t *len, size_t *cap) {
    switch (v->type) {
        case JSON_NULL:
            canon_ensure(buf, len, cap, 4);
            memcpy(*buf + *len, "null", 4); *len += 4;
