                snprintf(tmp, sizeof(tmp), "%lld", (long long)v->number);
            else
                snprintf(tmp, sizeof(tmp), "%.17g", v->number);
            size_t tl = strlen(tmp);
            canon_ensure(buf, len, cap, tl);
            memcpy(*buf + *len, tmp, tl); *len += tl;
            break;
        }
        case JSON_STRING: {
            canon_ensure(buf, len, cap, 2);
            (*buf)[(*len)++] = '"';
            for (const char *s = v->string; *s; s++) {
                char c = *s;
                if (c == '"' || c == '\\') {
                    canon_ensure(buf,len,cap,2);
                    (*buf)[(*len)++]='\\'; (*buf)[(*len)++]=c;
                } else if (c=='\n'){canon_ensure(buf,len,cap,2);(*buf)[(*len)++]='\\';(*buf)[(*len)++]='n';}
                else if (c=='\r'){canon_ensure(buf,len,cap,2);(*buf)[(*len)++]='\\';(*buf)[(*len)++]='r';}
                else if (c=='\t'){canon_ensure(buf,len,cap,2);(*buf)[(*len)++]='\\';(*buf)[(*len)++]='t';}
                else if (c=='\b'){canon_ensure(buf,len,cap,2);(*buf)[(*len)++]='\\';(*buf)[(*len)++]='b';}
                else if (c=='\f'){canon_ensure(buf,len,cap,2);(*buf)[(*len)++]='\\';(*buf)[(*len)++]='f';}
                else if ((unsigned char)c < 0x20) {
                    char esc[7]; snprintf(esc, sizeof(esc), "\\u%04x", (unsigned char)c);
                    canon_ensure(buf,len,cap,6); memcpy(*buf+*len,esc,6); *len+=6;
                } else {
                    canon_ensure(buf,len,cap,1);
                    (*buf)[(*len)++]=c;
                }
            }
            canon_ensure(buf, len, cap, 1);
            (*buf)[(*len)++] = '"';
            break;
        }
        case JSON_ARRAY: {
            canon_ensure(buf, len, cap, 1);
            (*buf)[(*len)++] = '[';
            for (size_t i = 0; i < v->array.count; i++) {
                if (i > 0) { canon_ensure(buf,len,cap,1); (*buf)[(*len)++]=','; }
                to_canon(v->array.items[i], buf, len, cap);
            }
            canon_ensure(buf, len, cap, 1);
            (*buf)[(*len)++] = ']';
            break;
        }
        case JSON_OBJECT: {
            canon_ensure(buf, len, cap, 1);
            (*buf)[(*len)++] = '{';
            size_t n = v->object.count;
            if (n > 0) {
                const char **keys = (const char **)malloc(n * sizeof(char *));
                for (size_t i = 0; i < n; i++) keys[i] = v->object.pairs[i].key;
                for (size_t i = 1; i < n; i++) {
                    const char *k = keys[i];
                    size_t j = i;
                    while (j > 0 && strcmp(keys[j-1], k) > 0) { keys[j]=keys[j-1]; j--; }
                    keys[j] = k;
