                for (size_t i = 0; i < n; i++) {
                    if (i > 0) { canon_ensure(buf,len,cap,1); (*buf)[(*len)++]=','; }
                    /* key */
                    canon_ensure(buf, len, cap, 2);
                    (*buf)[(*len)++] = '"';
                    for (const char *s = keys[i]; *s; s++) {
                        char c = *s;
                        if (c=='"'||c=='\\'){canon_ensure(buf,len,cap,2);(*buf)[(*len)++]='\\';(*buf)[(*len)++]=c;}
                        else if (c=='\n'){canon_ensure(buf,len,cap,2);(*buf)[(*len)++]='\\';(*buf)[(*len)++]='n';}
                        else if ((unsigned char)c<0x20){char esc[7];snprintf(esc,sizeof(esc),"\\u%04x",(unsigned char)c);canon_ensure(buf,len,cap,6);memcpy(*buf+*len,esc,6);*len+=6;}
                        else{canon_ensure(buf,len,cap,1);(*buf)[(*len)++]=c;}
