static JsonValue *merge_vals(const JsonValue *a, const JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *r = new_value(JSON_OBJECT);
        for (size_t i = 0; i < a->object.count; i++) {
            const char *key = a->object.pairs[i].key;
            JsonPair *bp = find_key(b, key);
            if (bp)
                obj_add(r, key, merge_vals(a->object.pairs[i].value, bp->value));
            else
                obj_add(r, key, deep_copy(a->object.pairs[i].value));
        }
        for (size_t i = 0; i < b->object.count; i++) {
            const char *key = b->object.pairs[i].key;
            if (!find_key(a, key))
                obj_add(r, key, deep_copy(b->object.pairs[i].value));
