        return r;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *r = new_value(JSON_ARRAY);
        for (size_t i = 0; i < a->array.count; i++)
            arr_add(r, deep_copy(a->array.items[i]));
        for (size_t i = 0; i < b->array.count; i++) {
            char *cb = get_canon(b->array.items[i]);
