            for (size_t j = 0; j < r->array.count; j++) {
                char *cr = get_canon(r->array.items[j]);
                if (strcmp(cb, cr) == 0) { found = 1; free(cr); break; }
                free(cr);
            }
            if (!found) arr_add(r, deep_copy(b->array.items[i]));
            free(cb);
        }
        return r;
    }
    return deep_copy(b);
