        case JSON_NUMBER: print_num(v->number, f); break;
        case JSON_STRING: print_escaped_str(v->string, f); break;
        case JSON_ARRAY: {
            if (v->array.count == 0) { fputs("[]", f); return; }
            fputs("[\n", f);
