#include <math.h>

typedef struct {
    int from, to;
    long long weight;
} Edge;

static char *read_file(const char *path, long *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)len + 1);
    if (!buf) { fclose(f); return NULL; }
    if (fread(buf, 1, (size_t)len, f) != (size_t)len) { free(buf); fclose(f); return NULL; }
    buf[len] = '\0';
    fclose(f);
    *out_len = len;
    return buf;
}

static void skip_ws(char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') (*p)++;
}

static char *parse_string(char **p) {
    skip_ws(p);
    if (**p != '"') return NULL;
    (*p)++;
    char *start = *p;
    while (**p && **p != '"') {
        if (**p == '\\') (*p)++;
        (*p)++;
    }
    int slen = (int)(*p - start);
    char *s = (char *)malloc((size_t)slen + 1);
    memcpy(s, start, (size_t)slen);
    s[slen] = '\0';
    if (**p == '"') (*p)++;
    return s;
}

static long long parse_number(char **p) {
    skip_ws(p);
    return strtoll(*p, p, 10);
}

typedef struct {
    int idx;
    const char *name;
} NodeRef;

static int cmp_noderef(const void *a, const void *b) {
    const NodeRef *ra = (const NodeRef *)a;
    const NodeRef *rb = (const NodeRef *)b;
    return strcmp(ra->name, rb->name);
}

