    p++;
    skip_ws(&p);
    while (*p != ']' && *p != '\0') {
        if (*p == ',') { p++; skip_ws(&p); continue; }
        if (*p == ']') break;
        if (*p != '"') { p++; continue; }
        char *s = parse_string(&p);
        if (!s) break;
        if (num_nodes >= cap_nodes) {
            cap_nodes *= 2;
            nodes = (char **)realloc(nodes, sizeof(char *) * (size_t)cap_nodes);
        }
        nodes[num_nodes++] = s;
        skip_ws(&p);
    }

    int cap_edges = 4096;
    int num_edges = 0;
    Edge *edges = (Edge *)malloc(sizeof(Edge) * (size_t)cap_edges);

