    while (*p != ']' && *p != '\0') {
        if (*p == ',') { p++; skip_ws(&p); continue; }
        if (*p == ']') break;
        if (*p != '{') { p++; continue; }
        p++;
        skip_ws(&p);

        int from_idx = -1, to_idx = -1;
        long long w = 0;
        int has_from = 0, has_to = 0, has_weight = 0;

        while (*p != '}' && *p != '\0') {
            if (*p == ',') { p++; skip_ws(&p); continue; }
            if (*p != '"') { p++; continue; }
            char *key = parse_string(&p);
            if (!key) break;
            skip_ws(&p);
            if (*p == ':') p++;
            skip_ws(&p);

            if (strcmp(key, "from") == 0) {
                char *val = parse_string(&p);
                if (val) {
                    for (int i = 0; i < num_nodes; i++) {
                        if (strcmp(nodes[i], val) == 0) { from_idx = i; break; }
                    }
                    free(val);
                    has_from = 1;
                }
            } else if (strcmp(key, "to") == 0) {
                char *val = parse_string(&p);
                if (val) {
                    for (int i = 0; i < num_nodes; i++) {
                        if (strcmp(nodes[i], val) == 0) { to_idx = i; break; }
                    }
                    free(val);
                    has_to = 1;
                }
            } else if (strcmp(key, "weight") == 0) {
