        for (int i = 0; i < num_nodes; i++) {
            if (!visited[i] && dist[i] < best) {
                best = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;
        for (int e = 0; e < num_edges; e++) {
