            if (edges[e].from == u) v = edges[e].to;
            else if (edges[e].to == u) v = edges[e].from;
            else continue;
            if (visited[v]) continue;
            long long nd = dist[u] + edges[e].weight;
            if (nd < dist[v]) dist[v] = nd;
        }
    }

    NodeRef *order = (NodeRef *)malloc(sizeof(NodeRef) * (size_t)num_nodes);
    for (int i = 0; i < num_nodes; i++) {
        order[i].idx = i;
        order[i].name = nodes[i];
    }
    qsort(order, (size_t)num_nodes, sizeof(NodeRef), cmp_noderef);

    printf("=== Shortest Paths from A ===\n");
    printf("\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i].idx;
        if (dist[idx] == INF) {
            printf("A -> %s: unreachable\n", nodes[idx]);
        } else {
            printf("A -> %s: %lld\n", nodes[idx], dist[idx]);
        }
    }

    for (int i = 0; i < num_nodes; i++) free(nodes[i]);
    free(nodes);
    free(edges);
    free(dist);
    free(visited);
    free(order);
    free(json);
    return 0;
}
